var n=`0586-kabuli-pulao`;var a=`world-0586`;var t=`AF`;var o=`south-asia`;var r=4;var s=141;var l={en:`Kabuli Pulao`,ua:`Кабулі-плов`};var u={en:`A traditional dish from Afghanistan, centered on lamb, yellow onion, basmati rice, carrot. A measured home-kitchen version organized by cooking step.`,ua:`Традиційна страва кухні країни Афганістан. Основні складники: ягнятина, жовта цибуля, рис басматі, морква. Домашній варіант із кількостями продуктів за етапами приготування.`};var d=[{en:`Pat the main ingredients dry. Brown in a hot heavy pan in batches for about 15 minutes, turning to color all sides.`,ua:`Обсушіть основні продукти. Обсмажуйте їх порціями на добре розігрітій важкій сковороді приблизно 15 хвилин, перевертаючи для рівної скоринки.`,t:[`searing`],m:15,i:[[`lamb`,850,`g`],[`yellow-onion`,230,`g`],[`sunflower-oil`,60,`ml`]]},{en:`Add the braising liquid and seasonings, cover and cook gently for about 80 minutes until the meat is tender and safely cooked.`,ua:`Додайте рідину та приправи для тушкування, накрийте кришкою й готуйте на малому вогні приблизно 80 хвилин до м’якості та повної готовності м’яса.`,t:[`braising`],m:80,i:[[`water`,750,`ml`],[`ground-cardamom`,5,`g`],[`ground-cinnamon`,4,`g`]]},{en:`Spread the rice evenly into the flavorful liquid. Cook uncovered or partly covered for about 30 minutes until the liquid is absorbed; do not over-stir.`,ua:`Рівномірно розподіліть рис у ароматній рідині. Готуйте приблизно 30 хвилин до вбирання рідини, не перемішуючи надмірно.`,t:[`rice-washing`,`absorption-cooking`],m:30,i:[[`basmati-rice`,510,`g`]]},{en:`Fry carrot matchsticks and raisins in a little oil with sugar, then scatter over fluffy rice, tender meat and almonds.`,ua:`Обсмажте морквяну соломку та родзинки з краплею олії й цукром, викладіть на розсипчастий рис із м’ясом та мигдалем.`,t:[`chopping`,`sauteing`],m:11,i:[[`carrot`,420,`g`],[`raisin`,120,`g`],[`white-granulated-sugar`,30,`g`],[`sunflower-oil`,30,`ml`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:5,i:[[`almond`,80,`g`]]}];var g={slug:n,id:a,country:`AF`,region:o,servings:4,minutes:141,title:l,text:u,steps:d};export{t as country,g as default,a as id,s as minutes,o as region,r as servings,n as slug,d as steps,u as text,l as title};